"""Starts the beta server of Northwind Lunch v2.0. Do not edit this file.

Run: python beta.py --help
"""
import argparse
import base64
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent


def main():
    parser = argparse.ArgumentParser(prog="beta.py", description="Start the beta server of Northwind Lunch v2.0.")
    parser.add_argument("--env", choices=["staging", "beta"], required=True,
                        help="where to start the server")
    parser.add_argument("--port", type=int, default=8000, help="the port number (default: %(default)s)")
    args = parser.parse_args()
    settings = json.loads((HERE / f"{args.env}.json").read_text(encoding="utf-8"))
    print(f"Starting the {settings['name']} server on port {args.port}...")
    if args.env != "beta":
        print("This is the staging server. Tonight we need the beta server.")
        return 1
    print("The beta server is running!")
    print("Code word:", base64.b64decode("c3Byb3V0").decode())
    return 0


if __name__ == "__main__":
    sys.exit(main())
